package sample_test
import ("context"; "testing"; "time"; "github.com/wyw14/cry-153/internal/sample"; "github.com/wyw14/cry-153/internal/station")
func TestSingleStationExitCannotCloseSharedSampleFanIn(t *testing.T){reg:=station.NewRegistry(); c:=sample.NewCoordinator(reg,4); ctx,cancel:=context.WithCancel(context.Background()); defer cancel(); c.StartSource(ctx,station.Source{ID:"fast",Values:[]float64{1}}); c.StartSource(ctx,station.Source{ID:"slow",Values:[]float64{2},Delay:100*time.Millisecond}); select{case _,ok:=<-c.Output():if !ok{t.Fatal("shared output closed while another source is active")};case <-time.After(time.Second):t.Fatal("fast source did not emit")}; select{case _,ok:=<-c.Output():if !ok{t.Fatal("shared output closed before slow source emitted")};case <-time.After(time.Second):t.Fatal("slow source did not emit")}; c.Close()}
